B.a19=s(["\uad11\uace0 \ubcf4\uace0 50\ubb38\uc7a5 \ucda9\uc804","\u0417\u0430\u0440 \u04af\u0437\u044d\u0436 50 \u04e9\u0433\u04af\u04af\u043b\u0431\u044d\u0440\u0438\u0439\u043d \u044d\u0440\u0445 \u0430\u0432\u0430\u0445"],t.s)
B.a1v=s(["\uccab \ubc88\uc9f8 \uad11\uace0 \ubcf4\uae30 (0/2)","\u042d\u0445\u043d\u0438\u0439 \u0437\u0430\u0440 \u04af\u0437\u044d\u0445 (0/2)"],t.s)
B.a5X=s(["\ub450 \ubc88\uc9f8 \uad11\uace0 \ubcf4\uae30 (1/2)","\u0425\u043e\u0451\u0440 \u0434\u0430\u0445\u044c \u0437\u0430\u0440 \u04af\u0437\u044d\u0445 (1/2)"],t.s)
B.a6q=s(["\uad11\uace0 \ubcf4\uace0 \ucda9\uc804","\u0417\u0430\u0440 \u04af\u0437\u044d\u0436 \u0446\u044d\u043d\u044d\u0433\u043b\u044d\u0445"],t.s)
B.a1X=s(["\ud68c\uc6d0 \ud0c8\ud1f4 \uc694\uccad","\u0411\u04af\u0440\u0442\u0433\u044d\u043b \u0443\u0441\u0442\u0433\u0430\u0445 \u0445\u04af\u0441\u044d\u043b\u0442"],t.s)
B.a15=s(["\ubcf8\uc778 \ud655\uc778 \ud6c4 \uc6b4\uc601\uc790\uc5d0\uac8c \ud0c8\ud1f4 \uc694\uccad\uc744 \uc811\uc218\ud569\ub2c8\ub2e4. \ucc98\ub9ac \uc644\ub8cc \uc2dc \ub85c\uadf8\uc778 \uacc4\uc815\xb7\uc804\ud654\ubc88\ud638 \uac80\uc0c9 \uc815\ubcf4\xb7\uc54c\ub9bc \uae30\uae30 \uc815\ubcf4\xb7\ub0a8\uc740 \uc774\uc6a9\uad8c\uc774 \uc0ad\uc81c\ub429\ub2c8\ub2e4. \uc694\uccad \uc811\uc218\ub9cc\uc73c\ub85c \uc989\uc2dc \ud0c8\ud1f4\ub418\uc9c0\ub294 \uc54a\uc73c\uba70, \uc644\ub8cc \uc608\uc815\uc77c\uacfc \uacb0\uacfc\ub294 \uc6b4\uc601\uc790\uc5d0\uac8c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\u0411\u0430\u0442\u0430\u043b\u0433\u0430\u0430\u0436\u0443\u0443\u043b\u0441\u043d\u044b \u0434\u0430\u0440\u0430\u0430 \u0430\u0434\u043c\u0438\u043d\u0434 \u0445\u04af\u0441\u044d\u043b\u0442 \u0438\u043b\u0433\u044d\u044d\u043d\u044d. \u0411\u04af\u0440\u044d\u043d \u0434\u0443\u0443\u0441\u0430\u0445\u0430\u0434 \u0431\u04af\u0440\u0442\u0433\u044d\u043b, \u0443\u0442\u0430\u0441\u043d\u044b \u0445\u0430\u0439\u043b\u0442, \u043c\u044d\u0434\u044d\u0433\u0434\u043b\u0438\u0439\u043d \u0442\u04e9\u0445\u04e9\u04e9\u0440\u04e9\u043c\u0436, \u04af\u043b\u0434\u0441\u044d\u043d \u044d\u0440\u0445 \u0443\u0441\u0442\u043d\u0430. \u0425\u04af\u0441\u044d\u043b\u0442 \u0448\u0443\u0443\u0434 \u0443\u0441\u0442\u0433\u0430\u0445\u0433\u04af\u0439. \u0425\u0443\u0433\u0430\u0446\u0430\u0430, \u04af\u0440 \u0434\u04af\u043d\u0433 \u0430\u0434\u043c\u0438\u043d\u0430\u0430\u0441 \u043b\u0430\u0432\u043b\u0430\u043d\u0430 \u0443\u0443."],t.s)
B.a0V=s(["\uc0c1\ub300\ubc29\uc5d0\uac8c \uc774\ubbf8 \uc804\ub2ec\ub41c \uc6d0\ubb38\uacfc \ubc88\uc5ed\ubb38\uc740 \uc0c1\ub300\ubc29 \uae30\ub85d\uc5d0 \ub0a8\uc2b5\ub2c8\ub2e4. \uc774\ub984\uc740 \u2018\ud0c8\ud1f4\ud55c \uc0ac\uc6a9\uc790\u2019\ub85c \ud45c\uc2dc\ub429\ub2c8\ub2e4. \ub2e4\uc2dc \uac00\uc785\ud574\ub3c4 \uc774\uc804 \ub300\ud654\uc5d0 \uc811\uadfc\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.","\u041d\u04e9\u0433\u04e9\u04e9 \u0445\u04af\u043d\u0434 \u0445\u04af\u0440\u0441\u044d\u043d \u044d\u0445 \u0431\u043e\u043b\u043e\u043d \u043e\u0440\u0447\u0443\u0443\u043b\u0441\u0430\u043d \u0437\u0443\u0440\u0432\u0430\u0441 \u0442\u04af\u04af\u043d\u0438\u0439 \u0447\u0430\u0442\u0430\u0434 \u04af\u043b\u0434\u044d\u043d\u044d. \u041d\u044d\u0440\u0438\u0439\u0433 \u201c\u0411\u04af\u0440\u0442\u0433\u044d\u043b\u044d\u044d \u0443\u0441\u0442\u0433\u0430\u0441\u0430\u043d \u0445\u044d\u0440\u044d\u0433\u043b\u044d\u0433\u0447\u201d \u0433\u044d\u0436 \u0445\u0430\u0440\u0443\u0443\u043b\u043d\u0430. \u0414\u0430\u0445\u0438\u043d \u0431\u04af\u0440\u0442\u0433\u04af\u04af\u043b\u0441\u044d\u043d \u0447 \u0445\u0443\u0443\u0447\u0438\u043d \u0447\u0430\u0442\u0430\u0434 \u043d\u044d\u0432\u0442\u0440\u044d\u0445\u0433\u04af\u0439."],t.s)
B.a1e=s(["\ub300\ud654 \ubcf8\ubb38 \uc18d \uac1c\uc778\uc815\ubcf4 \uc0ad\uc81c\ub098 \ubcc4\ub3c4 \uac1c\uc778\uc815\ubcf4 \uc694\uccad\uc740 \uc544\ub798 \uc774\uba54\uc77c\ub85c \ubb38\uc758\ud574 \uc8fc\uc138\uc694. \ube44\ubc00\ubc88\ud638\ub294 \uc774\uba54\uc77c\ub85c \ubcf4\ub0b4\uc9c0 \ub9c8\uc138\uc694.","\u0417\u0443\u0440\u0432\u0430\u0441 \u0434\u043e\u0442\u043e\u0440\u0445 \u0445\u0443\u0432\u0438\u0439\u043d \u043c\u044d\u0434\u044d\u044d\u043b\u044d\u043b \u0443\u0441\u0442\u0433\u0443\u0443\u043b\u0430\u0445 \u0431\u043e\u043b\u043e\u043d \u0431\u0443\u0441\u0430\u0434 \u0445\u04af\u0441\u044d\u043b\u0442\u0438\u0439\u0433 \u0434\u043e\u043e\u0440\u0445 \u0438\u043c\u044d\u0439\u043b\u044d\u044d\u0440 \u0433\u0430\u0440\u0433\u0430\u043d\u0430 \u0443\u0443. \u041d\u0443\u0443\u0446 \u04af\u0433\u044d\u044d \u0438\u043c\u044d\u0439\u043b\u044d\u044d\u0440 \u0431\u04af\u04af \u0438\u043b\u0433\u044d\u044d\u0433\u044d\u044d\u0440\u044d\u0439."],t.s)
B.a4M=s(["\uc0ad\uc81c\ub418\ub294 \uacc4\uc815 \uc815\ubcf4\uc640 \uc0c1\ub300\ubc29 \ub300\ud654 \ubcf4\uc874 \ubc94\uc704\ub97c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.","\u0423\u0441\u0442\u0430\u0445 \u0431\u04af\u0440\u0442\u0433\u044d\u043b\u0438\u0439\u043d \u043c\u044d\u0434\u044d\u044d\u043b\u044d\u043b \u0431\u043e\u043b\u043e\u043d \u043d\u04e9\u0433\u04e9\u04e9 \u0445\u04af\u043d\u0438\u0439 \u0447\u0430\u0442 \u0445\u0430\u0434\u0433\u0430\u043b\u0430\u0433\u0434\u0430\u0445\u044b\u0433 \u043e\u0439\u043b\u0433\u043e\u043b\u043e\u043e."],t.s)
