B.a5D=s(["\ud0c8\ud1f4 \uc694\uccad\uc774 \uc811\uc218\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \ucc98\ub9ac \uc608\uc815\uc77c\xb7\uc9c4\ud589 \uc0c1\ud0dc\xb7\uc694\uccad \ucde8\uc18c\ub294 dntprbs@gmail.com\uc73c\ub85c \ubb38\uc758\ud574 \uc8fc\uc138\uc694.","\u0423\u0441\u0442\u0433\u0430\u0445 \u0445\u04af\u0441\u044d\u043b\u0442\u0438\u0439\u0433 \u0445\u04af\u043b\u044d\u044d\u043d \u0430\u0432\u043b\u0430\u0430. \u0425\u0443\u0433\u0430\u0446\u0430\u0430, \u044f\u0432\u0446, \u0446\u0443\u0446\u043b\u0430\u0445 \u0445\u04af\u0441\u044d\u043b\u0442\u044d\u044d dntprbs@gmail.com \u0445\u0430\u044f\u0433\u0430\u0430\u0440 \u043b\u0430\u0432\u043b\u0430\u043d\u0430 \u0443\u0443."],t.s)
B.a1R=s(["\uc694\uccad\uc744 \uc811\uc218\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \ub85c\uadf8\uc778 \uc815\ubcf4\uc640 \uc778\ud130\ub137 \uc5f0\uacb0\uc744 \ud655\uc778\ud558\uac70\ub098 \ubb38\uc758 \uc774\uba54\uc77c\ub85c \uc5f0\ub77d\ud574 \uc8fc\uc138\uc694.","\u0425\u04af\u0441\u044d\u043b\u0442 \u0438\u043b\u0433\u044d\u044d\u0436 \u0447\u0430\u0434\u0441\u0430\u043d\u0433\u04af\u0439. \u041d\u044d\u0432\u0442\u0440\u044d\u0445 \u043c\u044d\u0434\u044d\u044d\u043b\u044d\u043b, \u0438\u043d\u0442\u0435\u0440\u043d\u044d\u0442\u044d\u044d \u0448\u0430\u043b\u0433\u0430\u0445 \u044d\u0441\u0432\u044d\u043b \u0438\u043c\u044d\u0439\u043b\u044d\u044d\u0440 \u0445\u043e\u043b\u0431\u043e\u0433\u0434\u043e\u043d\u043e \u0443\u0443."],t.s)
B.a5p=s(["\uc571\uc744 \uc9c0\uc6b4 \ud6c4\uc5d0\ub3c4 \uc678\ubd80 \uc548\ub0b4 \ud398\uc774\uc9c0\uc640 \ubb38\uc758 \uc774\uba54\uc77c\ub85c \uacc4\uc815 \uc0ad\uc81c\ub97c \uc694\uccad\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\u0410\u043f\u043f\u044b\u0433 \u0443\u0441\u0442\u0433\u0430\u0441\u0430\u043d \u0447 \u0433\u0430\u0434\u0430\u0430\u0434 \u0445\u0443\u0443\u0434\u0430\u0441 \u0431\u043e\u043b\u043e\u043d \u0438\u043c\u044d\u0439\u043b\u044d\u044d\u0440 \u0431\u04af\u0440\u0442\u0433\u044d\u043b \u0443\u0441\u0442\u0433\u0443\u0443\u043b\u0430\u0445 \u0445\u04af\u0441\u044d\u043b\u0442 \u0433\u0430\u0440\u0433\u0430\u0436 \u0431\u043e\u043b\u043d\u043e."],t.s)
B.a4F=s(["\uc678\ubd80 \ud0c8\ud1f4 \uc548\ub0b4 \uc8fc\uc18c \ubcf5\uc0ac","\u0413\u0430\u0434\u0430\u0430\u0434 \u0445\u04af\u0441\u044d\u043b\u0442\u0438\u0439\u043d \u0445\u043e\u043b\u0431\u043e\u043e\u0441 \u0445\u0443\u0443\u043b\u0430\u0445"],t.s)
B.a5y=s(["\uc548\ub0b4 \uc8fc\uc18c\ub97c \ubcf5\uc0ac\ud588\uc2b5\ub2c8\ub2e4.","\u0425\u043e\u043b\u0431\u043e\u043e\u0441\u044b\u0433 \u0445\u0443\u0443\u043b\u043b\u0430\u0430."],t.s)
